   583  htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
   584  {
   585      char smode[101], *cp, *cp2, *mode_c;
   586      htsFile *fp = NULL;
   587      hFILE *hfile = NULL;
   588      char fmt_code = '\0';
   589      const char format_to_mode[] = "\0g\0\0b\0c\0\0b\0g\0\0";
   590
   591      strncpy(smode, mode, 99);
   592      smode[99]=0;
   593      if ((cp = strchr(smode, ',')))
   594          *cp = '\0';
   595
   596      // Migrate format code (b or c) to the end of the smode buffer.
   597      for (cp2 = cp = smode; *cp; cp++) {
   598          if (*cp == 'b')
   599              fmt_code = 'b';
   600          else if (*cp == 'c')
   601              fmt_code = 'c';
   602          else
   603              *cp2++ = *cp;
   604      }
   605      mode_c = cp2;
   606      *cp2++ = fmt_code;
   607      *cp2++ = 0;
   608
   609      // Set or reset the format code if opts->format is used
   610      if (fmt && fmt->format > unknown_format
   611          && fmt->format < sizeof(format_to_mode)) {
   612          *mode_c = format_to_mode[fmt->format];
   613      }
   614
   615      // If we really asked for a compressed text format then mode_c above will
   616      // point to nul.  We set to 'z' to enable bgzf.
   617      if (strchr(mode, 'w') && fmt && fmt->compression == bgzf) {
   618          if (fmt->format == sam || fmt->format == vcf || fmt->format == text_format)
   619              *mode_c = 'z';
   620      }
   621
   622      char *rmme = NULL, *fnidx = strstr(fn, HTS_IDX_DELIM);
   623      if ( fnidx ) {
   624          rmme = strdup(fn);
   625          if ( !rmme ) goto error;
   626          rmme[fnidx-fn] = 0;
   627          fn = rmme;
   628      }
   629
   630      hfile = hopen(fn, smode);
   631      if (hfile == NULL) goto error;
   632
   633      fp = hts_hopen(hfile, fn, smode);
   634      if (fp == NULL) goto error;
   635
   636      // Compensate for the loss of exactness in htsExactFormat.
   637      // hts_hopen returns generics such as binary or text, but we
   638      // have been given something explicit here so use that instead.
   639      if (fp->is_write && fmt &&
   640          (fmt->format == bam || fmt->format == sam ||
   641           fmt->format == vcf || fmt->format == bcf ||
   642           fmt->format == bed || fmt->format == fasta_format ||
   643           fmt->format == fastq_format))
   644          fp->format.format = fmt->format;
   645
   646      if (fmt && fmt->specific)
   647          if (hts_opt_apply(fp, fmt->specific) != 0)
   648              goto error;
