   650      if ( rmme ) free(rmme);
   651      return fp;
   652
   653  error:
   654      hts_log_error("Failed to open file \"%s\"%s%s", fn,
   655                    errno ? " : " : "", errno ? strerror(errno) : "");
   656      if ( rmme ) free(rmme);
   657
   658      if (hfile)
   659          hclose_abruptly(hfile);
   660
   661      return NULL;
   662  }
